using ETulong;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Design;
namespace ETulongData;
public sealed class DeskDb(DbContextOptions<DeskDb> options):DbContext(options) {
 public DbSet<AidProgram> Programs=>Set<AidProgram>();public DbSet<RequirementType> Requirements=>Set<RequirementType>();public DbSet<ProgramRequirement> ProgramRequirements=>Set<ProgramRequirement>();public DbSet<AssistanceBatch> Batches=>Set<AssistanceBatch>();public DbSet<Applicant> Applicants=>Set<Applicant>();public DbSet<StaffUser> Staff=>Set<StaffUser>();public DbSet<ApplicationCase> Applications=>Set<ApplicationCase>();public DbSet<SubmittedDocument> Documents=>Set<SubmittedDocument>();public DbSet<SlotReservation> Reservations=>Set<SlotReservation>();public DbSet<Approval> Approvals=>Set<Approval>();public DbSet<ClaimVerification> Verifications=>Set<ClaimVerification>();
 protected override void OnModelCreating(ModelBuilder b){
 b.Entity<AidProgram>().ToTable("Programs");b.Entity<RequirementType>().ToTable("Requirements");b.Entity<StaffUser>().ToTable("Staff");b.Entity<Applicant>().ToTable("Applicants");
 b.Entity<ProgramRequirement>().ToTable("ProgramRequirements").HasKey(x=>new{x.ProgramId,x.RequirementId});
 b.Entity<ProgramRequirement>().HasOne<AidProgram>().WithMany().HasForeignKey(x=>x.ProgramId).OnDelete(DeleteBehavior.Restrict);b.Entity<ProgramRequirement>().HasOne<RequirementType>().WithMany().HasForeignKey(x=>x.RequirementId).OnDelete(DeleteBehavior.Restrict);
 b.Entity<AssistanceBatch>().ToTable("AssistanceBatches",t=>t.HasCheckConstraint("capacity_valid",""" "Capacity">0 AND "ReservedCount">=0 AND "ReservedCount"<="Capacity" """));b.Entity<AssistanceBatch>().HasOne<AidProgram>().WithMany().HasForeignKey(x=>x.ProgramId).OnDelete(DeleteBehavior.Restrict);
 b.Entity<Applicant>().HasIndex(x=>x.Reference).IsUnique();
 b.Entity<ApplicationCase>().ToTable("Applications",t=>t.HasCheckConstraint("case_status",""" "Status" IN ('Draft','Submitted','NeedsResubmission','Endorsed','Approved','Denied','Scheduled','Held','Released') """));b.Entity<ApplicationCase>().HasIndex(x=>new{x.ApplicantId,x.BatchId}).IsUnique();b.Entity<ApplicationCase>().HasOne<Applicant>().WithMany().HasForeignKey(x=>x.ApplicantId).OnDelete(DeleteBehavior.Restrict);b.Entity<ApplicationCase>().HasOne<AssistanceBatch>().WithMany().HasForeignKey(x=>x.BatchId).OnDelete(DeleteBehavior.Restrict);b.Entity<ApplicationCase>().HasIndex(x=>new{x.Status,x.Id});
 b.Entity<SubmittedDocument>().ToTable("Documents",t=>t.HasCheckConstraint("document_decision",""" "Decision" IN ('Pending','Accepted','Resubmit','Rejected') """));b.Entity<SubmittedDocument>().HasIndex(x=>new{x.CaseId,x.RequirementId}).IsUnique();b.Entity<SubmittedDocument>().HasOne<ApplicationCase>().WithMany().HasForeignKey(x=>x.CaseId).OnDelete(DeleteBehavior.Restrict);b.Entity<SubmittedDocument>().HasOne<RequirementType>().WithMany().HasForeignKey(x=>x.RequirementId).OnDelete(DeleteBehavior.Restrict);b.Entity<SubmittedDocument>().HasOne<StaffUser>().WithMany().HasForeignKey(x=>x.ReviewedBy).OnDelete(DeleteBehavior.Restrict);
 b.Entity<SlotReservation>().ToTable("Reservations",t=>t.HasCheckConstraint("reservation_state",""" "State" IN ('Reserved','Awarded','Released') """));b.Entity<SlotReservation>().HasIndex(x=>x.CaseId).IsUnique();b.Entity<SlotReservation>().HasOne<ApplicationCase>().WithMany().HasForeignKey(x=>x.CaseId).OnDelete(DeleteBehavior.Restrict);b.Entity<SlotReservation>().HasOne<AssistanceBatch>().WithMany().HasForeignKey(x=>x.BatchId).OnDelete(DeleteBehavior.Restrict);
 b.Entity<Approval>().ToTable("Approvals");b.Entity<Approval>().HasIndex(x=>x.CaseId).IsUnique();b.Entity<Approval>().HasOne<ApplicationCase>().WithMany().HasForeignKey(x=>x.CaseId).OnDelete(DeleteBehavior.Restrict);b.Entity<Approval>().HasOne<StaffUser>().WithMany().HasForeignKey(x=>x.OfficialId).OnDelete(DeleteBehavior.Restrict);
 b.Entity<ClaimVerification>().ToTable("Verifications");b.Entity<ClaimVerification>().HasIndex(x=>x.CaseId).IsUnique().HasFilter(""" "Result"='Released' """);b.Entity<ClaimVerification>().HasOne<ApplicationCase>().WithMany().HasForeignKey(x=>x.CaseId).OnDelete(DeleteBehavior.Restrict);b.Entity<ClaimVerification>().HasOne<StaffUser>().WithMany().HasForeignKey(x=>x.OfficerId).OnDelete(DeleteBehavior.Restrict);
 }
}
public sealed class DesignFactory:IDesignTimeDbContextFactory<DeskDb>{public DeskDb CreateDbContext(string[] args)=>new(new DbContextOptionsBuilder<DeskDb>().UseNpgsql(Environment.GetEnvironmentVariable("ETULONG_DB")??"Host=localhost;Database=etulong;Username=postgres").Options);}
